const frag = $input.all().filter(i => typeof i.json.score === 'number' && i.json.document);
const pregunta = $('Chat de Prueba (test ciego)').first().json.chatInput;
return [{ json: {
  pregunta,
  hay_fragmentos: frag.length > 0,
  cantidad_fragmentos: frag.length,
  scores: frag.map(f => Math.round(f.json.score * 100) / 100),
  contexto: frag.map((f, i) => `[Fragmento ${i + 1} | score ${f.json.score.toFixed(2)}]\n${f.json.document.pageContent}`).join('\n\n---\n\n')
} }];

