// COMPLIANCE · destruccion binaria
// El audio del cliente (Telegram) y el audio generado (ElevenLabs) solo viven dentro de
// esta ejecucion. Este nodo corta la cadena: no devuelve binarios, ni la transcripcion,
// ni el chat_id. Con "Save executions = Do not save" n8n borra la ejecucion al cerrar el
// flujo; con N8N_DEFAULT_BINARY_DATA_MODE=default + EXECUTIONS_DATA_HARD_DELETE_BUFFER=0
// los binarios quedan solo en RAM y la purga fisica ocurre en menos de 1 minuto.
const ruta = $prevNode.name === 'Telegram · Send Audio (respuesta)'
  ? 'respuesta_de_voz'
  : 'contingencia_audio_invalido';

return $input.all().map(() => ({
  json: {
    canal: 'telegram_voz',
    ruta,
    binarios_retenidos: 0,
    transcripcion_retenida: false,
    cerrado_en: $now.toISO(),
  },
}));
